Here is the root cause:
The bug was caused by a mismatch between the format specifier used in the `snprintf` function and the actual type of the argument being passed. The original code used `%lu` for a `u64` type variable (`cgrp_id`), which is incorrect and leads to a build error on 32-bit systems where the compiler treats this as a warning and fails the build due to the `-Werror=format=` flag. The correct format specifier for `u64` is `%llu`, which was not used in the original code.

Here is the patch:
 #include <linux/string.h>
 #include <bpf/bpf.h>
+#include <inttypes.h>

 #include "bpf_skel/lock_contention.skel.h"

 static const char *lock_contention_get_name(struct lock_contention *con,
 					    struct contention_key *key,
 					    u64 *stack_trace, u32 flags)
 {
 	int idx = 0;
 	u64 addr;
 	const char *name = "";
 	static char name_buf[KSYM_NAME_LEN];
 	struct symbol *sym;
 	struct map *kmap;
 	struct machine *machine = con->machine;

 	if (con->aggr_mode == LOCK_AGGR_TASK) {
 		struct contention_task_data task;
 		int pid = key->pid;
 		int task_fd = bpf_map__fd(skel->maps.task_data);

 		/* do not update idle comm which contains CPU number */
 		if (pid) {
 			struct thread *t = __machine__findnew_thread(machine, /*pid=*/-1, pid);

 			if (t == NULL)
 				return name;
 			if (!bpf_map_lookup_elem(task_fd, &pid, &task) &&
 			    thread__set_comm(t, task.comm, /*timestamp=*/0))
 				name = task.comm;
 		}
 		return name;
 	}

 	if (con->aggr_mode == LOCK_AGGR_ADDR) {
 		int lock_fd = bpf_map__fd(skel->maps.lock_syms);

 		/* per-process locks set upper bits of the flags */
 		if (flags & LCD_F_MMAP_LOCK)
 			return "mmap_lock";
 		if (flags & LCD_F_SIGHAND_LOCK)
 			return "siglock";

 		/* global locks with symbols */
 		sym = machine__find_kernel_symbol(machine, key->lock_addr_or_cgroup, &kmap);
 		if (sym)
 			return sym->name;

 		/* try semi-global locks collected separately */
 		if (!bpf_map_lookup_elem(lock_fd, &key->lock_addr_or_cgroup, &flags)) {
 			if (flags == LOCK_CLASS_RQLOCK)
 				return "rq_lock";
 		}

 		return "";
 	}

 	if (con->aggr_mode == LOCK_AGGR_CGROUP) {
 		u64 cgrp_id = key->lock_addr_or_cgroup;
 		struct cgroup *cgrp = __cgroup__find(&con->cgroups, cgrp_id);

 		if (cgrp)
 			return cgrp->name;

-		snprintf(name_buf, sizeof(name_buf), "cgroup:%lu", cgrp_id);
+		snprintf(name_buf, sizeof(name_buf), "cgroup:%" PRIu64 "", cgrp_id);
 		return name_buf;
 	}

 	/* LOCK_AGGR_CALLER: skip lock internal functions */
 	while (machine__is_lock_function(machine, stack_trace[idx]) &&
 	       idx < con->max_stack - 1)
 		idx++;

 	addr = stack_trace[idx];
 	sym = machine__find_kernel_symbol(machine, addr, &kmap);

 	if (sym) {
 		unsigned long offset;

 		offset = map__map_ip(kmap, addr) - sym->start;

 		if (offset == 0)
 			return sym->name;

 		snprintf(name_buf, sizeof(name_buf), "%s+%#lx", sym->name, offset);
 	} else {
 		snprintf(name_buf, sizeof(name_buf), "%#lx", (unsigned long)addr);
 	}

 	return name_buf;
 }



